@Tags(['golden'])
library;

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:zaghlol/core/ocr/unavailable_ocr_engine.dart';
import 'package:zaghlol/features/capture/presentation/scan_confirm_screen.dart';

import '../../../support/golden_matrix.dart';
import '../../transactions/presentation/detail_edit_harness.dart';
import 'scan_confirm_screen_test.dart' show FakeOcr, scanOverrides;

// Goldens are generated by CI (`--update-goldens`); PNGs are not committed.
void main() {
  for (final v in goldenVariants) {
    testWidgets('S-32 found golden ${v.name}', (t) async {
      await t.binding.setSurfaceSize(const Size(390, 844));
      addTearDown(() => t.binding.setSurfaceSize(null));
      await t.pumpWidget(
        harnessApp(
          scanOverrides(
            FakeEditor(),
            FakeOcr(
              'Transfer successful\nEGP 1,250.00\nTo: ahmed.ali@instapay\n'
              'From account: **** 4567\nDate: 23/10/2026',
            ),
          ),
          const ScanConfirmScreen(request: ScanImagePath('/p')),
          locale: v.locale,
          dark: v.dark,
        ),
      );
      await t.pumpAndSettle();
      await expectLater(
        find.byType(MaterialApp),
        matchesGoldenFile('../../../goldens/scan_found_${v.name}.png'),
      );
    });

    testWidgets('S-32 not available golden ${v.name}', (t) async {
      await t.binding.setSurfaceSize(const Size(390, 600));
      addTearDown(() => t.binding.setSurfaceSize(null));
      await t.pumpWidget(
        harnessApp(
          scanOverrides(FakeEditor(), const UnavailableOcrEngine()),
          const ScanConfirmScreen(),
          locale: v.locale,
          dark: v.dark,
        ),
      );
      await t.pumpAndSettle();
      await expectLater(
        find.byType(MaterialApp),
        matchesGoldenFile('../../../goldens/scan_unavailable_${v.name}.png'),
      );
    });
  }
}
